def _finite_non_bool(value: object) -> float:
    """Return ``float(value)`` for a non-bool finite number, else raise."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError("value must be a finite non-bool number")
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("value must be a finite non-bool number")
    return number


def _disk_covers(
    px: float, py: float, ox: float, oy: float, bound: float, slack: float
) -> bool:
    """Closed-disk test ``hypot(point - center) <= bound + slack``.

    Every input is finite, but the coordinate differences, the hypotenuse
    and the radius may individually overflow to ``inf`` for huge values.
    A one-sided overflow is decided by the overflow alone: an infinite
    distance exceeds any finite radius and an infinite radius covers any
    finite distance. Only when both sides overflow is the comparison
    redone at quarter scale — dividing by a power of two is exact and
    keeps every intermediate finite — so the true disk relation decides.
    """
    distance = math.hypot(px - ox, py - oy)
    radius = bound + slack
    if math.isinf(distance) and math.isinf(radius):
        distance = math.hypot(px / 4.0 - ox / 4.0, py / 4.0 - oy / 4.0)
        radius = bound / 4.0 + slack / 4.0
    return distance <= radius


def _slack_from_tolerance(tolerance: object) -> float:
    """Validate the shared ``tolerance`` keyword of the locate entries."""
    if isinstance(tolerance, bool) or not isinstance(tolerance, (int, float)):
        raise ValueError("tolerance must be a finite non-negative number")
    slack = float(tolerance)
    if not math.isfinite(slack) or slack < 0:
        raise ValueError("tolerance must be a finite non-negative number")
    return slack


def _point_coordinates(point: object) -> tuple[float, float]:
    """Validate the shared 2D candidate point of the locate entries."""
    if not isinstance(point, tuple) or len(point) != 2:
        raise ValueError("point must be a tuple of exactly two finite numbers")
    return _finite_non_bool(point[0]), _finite_non_bool(point[1])


def _materialize_observations(observations: object) -> list[object]:
    """Snapshot the shared observations iterable (lists and one-shot alike)."""
    try:
        return list(observations)  # type: ignore[arg-type]
    except TypeError as error:
        raise ValueError("observations must be an iterable of Observation") from error

